int main() {
    ios_base::sync_with_stdio(0); cin.tie(0);
    int n, m, MOD;
    while (cin >> n >> m >> MOD) {
        auto add_value = [&](ll &x, ll y) {
            x += y;
            if (x >= MOD) x -= MOD;
        };
        vector<vi> binom(m+1, vi(m+1));
        for (int i=0; i<=m; i++) {
            binom[i][0] = 1;
            for (int j=1; j<=i; j++) {
                binom[i][j] = binom[i-1][j-1] + binom[i-1][j];
