                add_mod(sum_part, sum[right] * ways[left] % MOD);
                add_mod(sum[size], (size+1) * binom[size-1][split] % MOD * sum_part % MOD);
                ll total_sum_part = 0;
                add_mod(total_sum_part, prefix_sum[left] * ways[right] % MOD);
                add_mod(total_sum_part, prefix_sum[right] * ways[left] % MOD);
                add_mod(sum[size], (size+1) * binom[size-1][split] % MOD * total_sum_part % MOD);
            }
        }
        vector<vi> ways2(n+1, vi(m+1)), sum2(n+1, vi(m+1));
        ways2[0][0] = 1;
        for (int i=1; i<=n; i++) {
            for (int j=0; j<=min(i,m); j++) {
                ways2[i][j] = ways2[i-1][j];
                sum2[i][j] = sum2[i-1][j];
                for (int k=1; k<=j; k++) {
                    int ni = max(0, i - k - 1);
                    int nj = j - k;
                    add_value(ways2[i][j], ways[k] * ways2[ni][nj] % MOD * binom[j][k] % MOD);
                    add_value(sum2[i][j], (sum[k] * ways2[ni][nj] + ways[k] * sum2[ni][nj]) % MOD * binom[j][k] % MOD);
